function newestMtime(dir: string): number {
	let newest = 0;
	for (const item of readdirSync(dir, { withFileTypes: true })) {
		const full = path.join(dir, item.name);
		newest = Math.max(newest, item.isDirectory() ? newestMtime(full) : statSync(full).mtimeMs);
	}
	return newest;
}

function bucketFor(buckets: State["buckets"], inst: $ZodType): WeakMap<object, Entry> {
	let bucket = buckets.get(inst);
	if (!bucket) {
		bucket = new WeakMap();
		buckets.set(inst, bucket);
	}
	return bucket;
}

