async synchronize(dropBeforeSync: boolean = false): Promise<void> {
	if (!this.isInitialized) throw new CannotExecuteNotConnectedError()

	if (dropBeforeSync) await this.dropDatabase()

	const schemaBuilder = this.driver.createSchemaBuilder()
	await schemaBuilder.build()
}

async release(): Promise<void> {
	this.isReleased = true
	if (this.session) {
		await this.session.delete()
	}
	this.session = undefined
	return Promise.resolve()
}

async disconnect(): Promise<void> {
	return new Promise<void>((ok, fail) => {
		this.queryRunner = undefined
		this.databaseConnection.close((err: any) =>
			err ? fail(err) : ok(),
		)
	})
}

async hasTable(tableOrName: Table | string): Promise<boolean> {
	const tableName = InstanceChecker.isTable(tableOrName)
		? tableOrName.name
		: tableOrName
	const sql = `SELECT * FROM "sqlite_master" WHERE "type" = 'table' AND "name" = ?`
	const result = await this.query(sql, [tableName])
	return result.length ? true : false
}

