function uniqueNodes(arr: any[]) {
	const res = []
	for (let i = 0, len = arr.length; i < len; i++) {
		const edge: any = arr[i]
		if (res.indexOf(edge[0]) < 0) res.push(edge[0])
		if (res.indexOf(edge[1]) < 0) res.push(edge[1])
	}
	return res
}

